  `address` text COLLATE utf8mb4_unicode_ci,
  `tax_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_vat_payer` tinyint(1) DEFAULT '0',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `details_json` json DEFAULT NULL COMMENT 'Всі реквізити платника',
  `legal_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Юридична назва',
  `signatory_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ПІБ підписанта',
  `signatory_basis` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'На підставі чого діє',
  `email_for_docs` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_for_docs` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by_user_id` int(11) DEFAULT NULL COMMENT 'Хто створив (менеджер)',
  `active_master_agreement_id` int(11) DEFAULT NULL COMMENT 'Активний рамковий договір для цього платника'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

