--
-- Структура таблиці `products`
--

CREATE TABLE `products` (
  `product_id` int(11) NOT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `name` varchar(500) DEFAULT NULL,
  `category_id` int(11) DEFAULT NULL,
  `category_name` varchar(255) DEFAULT NULL,
  `subcategory_id` int(11) DEFAULT NULL,
  `subcategory_name` varchar(255) DEFAULT NULL,
  `description` text,
  `care_instructions` text,
  `color` varchar(100) DEFAULT NULL,
  `material` varchar(100) DEFAULT NULL,
  `size` varchar(100) DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `rental_price` decimal(10,2) DEFAULT NULL,
  `status` tinyint(4) DEFAULT '1',
  `quantity` int(11) DEFAULT '0',
  `image_url` varchar(500) DEFAULT NULL,
  `synced_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `zone` varchar(50) DEFAULT NULL,
  `aisle` varchar(50) DEFAULT NULL,
  `shelf` varchar(50) DEFAULT NULL,
  `cleaning_status` varchar(50) DEFAULT NULL,
  `product_state` varchar(50) DEFAULT NULL,
  `last_audit_date` date DEFAULT NULL,
  `family_id` int(11) DEFAULT NULL,
  `frozen_quantity` int(11) DEFAULT '0' COMMENT 'Кількість замороженого товару (в ремонті/мийці/реставрації)',
  `in_laundry` int(11) DEFAULT '0',
  `laundry_batch_id` varchar(36) DEFAULT NULL,
  `state` varchar(50) DEFAULT 'available' COMMENT 'Стан товару: available, damaged, in_repair, lost',
  `height_cm` decimal(10,2) DEFAULT NULL COMMENT 'Висота в см',
  `width_cm` decimal(10,2) DEFAULT NULL COMMENT 'Ширина в см',
  `depth_cm` decimal(10,2) DEFAULT NULL COMMENT 'Глибина в см',
  `diameter_cm` decimal(10,2) DEFAULT NULL COMMENT 'Діаметр в см',
  `shape` varchar(100) DEFAULT NULL COMMENT 'Форма виробу (круглий, квадратний, овальний...)',
  `components` text,
  `hashtags` json DEFAULT NULL COMMENT 'Масив хештегів для фільтрації ["весілля", "вінтаж", "золото"]',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_pushed_to_oc` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- --------------------------------------------------------

--
-- Структура таблиці `product_damage_history`
--

CREATE TABLE `product_damage_history` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_id` int(11) NOT NULL,
  `sku` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_id` int(11) DEFAULT NULL,
  `order_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stage` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `damage_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `damage_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'low',
  `fee` decimal(10,2) DEFAULT '0.00',
  `photo_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `processing_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'none',
  `processing_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `sent_to_processing_at` datetime DEFAULT NULL,
  `returned_from_processing_at` datetime DEFAULT NULL,
  `processing_notes` text COLLATE utf8mb4_unicode_ci,
  `laundry_batch_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `laundry_item_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `created_by_id` int(11) DEFAULT NULL COMMENT 'ID користувача що зафіксував пошкодження',
  `qty` int(11) DEFAULT '1',
  `processed_qty` int(11) DEFAULT '0',
  `fee_per_item` decimal(10,2) DEFAULT '0.00',
  `base_value` decimal(10,2) DEFAULT NULL,
  `estimate_value` decimal(10,2) DEFAULT NULL,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

