--
-- Структура для представлення `v_order_finance`
--
DROP TABLE IF EXISTS `v_order_finance`;

CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_order_finance`  AS SELECT `o`.`order_id` AS `order_id`, `o`.`order_number` AS `order_number`, `o`.`status` AS `status`, `o`.`customer_name` AS `customer_name`, coalesce(`o`.`total_price`,0) AS `total_rental`, coalesce(`o`.`discount_amount`,0) AS `discount_amount`, coalesce(`o`.`discount_percent`,0) AS `discount_percent`, coalesce(`o`.`deposit_amount`,0) AS `deposit_amount`, coalesce(`o`.`service_fee`,0) AS `service_fee`, ((coalesce(`o`.`total_price`,0) - coalesce(`o`.`discount_amount`,0)) + coalesce(`o`.`service_fee`,0)) AS `total_to_pay`, coalesce((select sum(`fin_transactions`.`amount`) from `fin_transactions` where ((`fin_transactions`.`entity_type` = 'order') and (`fin_transactions`.`entity_id` = `o`.`order_id`) and (`fin_transactions`.`tx_type` in ('rent_payment','additional_payment')) and isnull(`fin_transactions`.`voided_at`))),0) AS `paid_rent`, coalesce((select sum(`fin_transactions`.`amount`) from `fin_transactions` where ((`fin_transactions`.`entity_type` = 'order') and (`fin_transactions`.`entity_id` = `o`.`order_id`) and (`fin_transactions`.`tx_type` = 'deposit_payment') and isnull(`fin_transactions`.`voided_at`))),0) AS `paid_deposit`, coalesce((select sum(`fin_transactions`.`amount`) from `fin_transactions` where ((`fin_transactions`.`entity_type` = 'order') and (`fin_transactions`.`entity_id` = `o`.`order_id`) and (`fin_transactions`.`tx_type` = 'deposit_refund') and isnull(`fin_transactions`.`voided_at`))),0) AS `refunded_deposit`, coalesce((select sum(`fin_transactions`.`amount`) from `fin_transactions` where ((`fin_transactions`.`entity_type` = 'order') and (`fin_transactions`.`entity_id` = `o`.`order_id`) and (`fin_transactions`.`tx_type` in ('damage_deduction','damage_payment','collection','late_payment','charge')) and isnull(`fin_transactions`.`voided_at`))),0) AS `extra_charges`, greatest(((((coalesce(`o`.`total_price`,0) - coalesce(`o`.`discount_amount`,0)) + coalesce(`o`.`service_fee`,0)) + coalesce((select sum(`fin_transactions`.`amount`) from `fin_transactions` where ((`fin_transactions`.`entity_type` = 'order') and (`fin_transactions`.`entity_id` = `o`.`order_id`) and (`fin_transactions`.`tx_type` in ('damage_deduction','damage_payment','collection','late_payment','charge')) and isnull(`fin_transactions`.`voided_at`))),0)) - coalesce((select sum(`fin_transactions`.`amount`) from `fin_transactions` where ((`fin_transactions`.`entity_type` = 'order') and (`fin_transactions`.`entity_id` = `o`.`order_id`) and (`fin_transactions`.`tx_type` in ('rent_payment','additional_payment')) and isnull(`fin_transactions`.`voided_at`))),0)),0) AS `debt`, `o`.`created_at` AS `created_at`, `o`.`updated_at` AS `updated_at` FROM `orders` AS `o` ;

